INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('education', 'class-10/science', 'chemical-reactions', 'A reaction in which a single compound breaks down into two or more simpler substances is called a:', '["Decomposition reaction", "Combination reaction", "Displacement reaction", "Double displacement reaction"]', 0, 'A decomposition reaction is one where a single compound splits into two or more simpler products, often needing heat, light, or electricity.', 'beginner'),
('education', 'class-10/science', 'chemical-reactions', 'The reaction Zn + CuSO4 -> ZnSO4 + Cu is an example of a:', '["Displacement reaction", "Decomposition reaction", "Combination reaction", "Neutralization reaction"]', 0, 'Zinc, being more reactive than copper, displaces copper from copper sulphate solution -- a classic single displacement reaction.', 'beginner'),
('education', 'class-10/science', 'chemical-reactions', 'Rusting of iron is primarily an example of a(n):', '["Oxidation reaction", "Reduction reaction", "Decomposition reaction", "Displacement reaction"]', 0, 'Rusting involves iron reacting with oxygen and moisture to form iron oxide (Fe2O3.xH2O) -- iron is oxidized in this redox process.', 'beginner'),
('education', 'class-10/science', 'chemical-reactions', 'Balancing a chemical equation is necessary because of the:', '["Law of Conservation of Mass", "Law of Conservation of Energy", "Law of Definite Proportions only", "Law of Multiple Proportions"]', 0, 'The Law of Conservation of Mass requires that the number of atoms of each element be equal on both sides of a balanced equation.', 'beginner'),
('education', 'class-10/science', 'chemical-reactions', 'When quicklime (CaO) reacts with water to form slaked lime, the reaction type and nature are:', '["Combination reaction, exothermic", "Decomposition reaction, endothermic", "Displacement reaction, exothermic", "Combination reaction, endothermic"]', 0, 'CaO + H2O -> Ca(OH)2 combines two substances into one product and releases a large amount of heat, making it exothermic.', 'intermediate'),
('education', 'class-10/science', 'acids-bases-salts', 'The pH value of a neutral solution (such as pure water) is:', '["7", "0", "14", "1"]', 0, 'A pH of 7 indicates a neutral solution; values below 7 are acidic and above 7 are basic.', 'beginner'),
('education', 'class-10/science', 'acids-bases-salts', 'The common salt formed when hydrochloric acid reacts with sodium hydroxide is:', '["Sodium chloride (NaCl)", "Sodium sulphate (Na2SO4)", "Sodium carbonate (Na2CO3)", "Sodium nitrate (NaNO3)"]', 0, 'HCl + NaOH -> NaCl + H2O is a standard neutralization reaction producing common salt and water.', 'beginner'),
('education', 'class-10/science', 'acids-bases-salts', 'The chemical formula of baking soda is:', '["NaHCO3", "Na2CO3", "NaOH", "CaCO3"]', 0, 'Baking soda is sodium hydrogen carbonate, NaHCO3.', 'beginner'),
('education', 'class-10/science', 'acids-bases-salts', 'Antacid tablets relieve acidity in the stomach because they:', '["Neutralize excess stomach acid", "Increase acid production", "Convert acid into water directly", "Coat the stomach lining only"]', 0, 'Antacids are mild bases (e.g. magnesium hydroxide) that neutralize excess hydrochloric acid in the stomach.', 'beginner'),
('education', 'class-10/science', 'acids-bases-salts', 'A solution with a pH value less than 7 is:', '["Acidic", "Basic", "Neutral", "Cannot be determined"]', 0, 'pH values below 7 indicate an acidic solution; the lower the value, the more strongly acidic.', 'beginner'),
('education', 'class-10/science', 'metals-nonmetals', 'The property of metals that allows them to be beaten into thin sheets is called:', '["Malleability", "Ductility", "Conductivity", "Sonority"]', 0, 'Malleability is the property that allows metals to be hammered or rolled into thin sheets without breaking.', 'beginner'),
('education', 'class-10/science', 'metals-nonmetals', 'Among common metals, which is placed highest (most reactive) in the reactivity series?', '["Potassium", "Iron", "Copper", "Gold"]', 0, 'Potassium is one of the most reactive metals, placed at or near the top of the standard reactivity series taught in CBSE Class 10.', 'intermediate'),
('education', 'class-10/science', 'metals-nonmetals', 'Ionic compounds generally have high melting and boiling points because:', '["Strong electrostatic forces hold the ions together", "They are covalently bonded", "They lack a definite structure", "They are always gases at room temperature"]', 0, 'Ionic compounds form a rigid lattice held together by strong electrostatic forces between oppositely charged ions, requiring significant energy to break.', 'intermediate'),
('education', 'class-10/science', 'metals-nonmetals', 'The process of coating iron with a thin layer of zinc to prevent rusting is called:', '["Galvanization", "Electrolysis", "Alloying", "Annealing"]', 0, 'Galvanization coats iron/steel with zinc, which corrodes preferentially and protects the underlying iron from rusting.', 'beginner'),
('education', 'class-10/science', 'metals-nonmetals', 'Non-metals are generally poor conductors of heat and electricity, with the notable exception of:', '["Graphite", "Sulphur", "Phosphorus", "Iodine"]', 0, 'Graphite, a non-metal (a form of carbon), is unusual in being a good conductor of electricity due to its layered structure of delocalized electrons.', 'intermediate'),
('education', 'class-10/science', 'carbon-compounds', 'The property of carbon that allows it to form long chains of carbon atoms is called:', '["Catenation", "Isomerism", "Tetravalency alone", "Allotropy"]', 0, 'Catenation is carbon''s distinctive ability to bond with other carbon atoms to form long chains, branched chains, and rings.', 'beginner'),
('education', 'class-10/science', 'carbon-compounds', 'A compound containing the functional group -OH belongs to which class?', '["Alcohols", "Aldehydes", "Ketones", "Carboxylic acids"]', 0, 'The -OH (hydroxyl) functional group is the defining feature of alcohols.', 'beginner'),
('education', 'class-10/science', 'carbon-compounds', 'The general formula for the alkane series of hydrocarbons is:', '["CnH2n+2", "CnH2n", "CnH2n-2", "CnHn"]', 0, 'Alkanes are saturated hydrocarbons following the general formula CnH2n+2.', 'beginner'),
('education', 'class-10/science', 'carbon-compounds', 'The common name for ethanoic acid is:', '["Acetic acid (vinegar)", "Formic acid", "Citric acid", "Lactic acid"]', 0, 'Ethanoic acid (CH3COOH) is commonly known as acetic acid, and a dilute solution of it is vinegar.', 'beginner'),
('education', 'class-10/science', 'carbon-compounds', 'A carbon atom can form how many covalent bonds with other atoms?', '["4", "2", "3", "6"]', 0, 'Carbon has 4 valence electrons and is tetravalent, forming exactly 4 covalent bonds.', 'beginner'),
('education', 'class-10/science', 'periodic-classification', 'The Modern Periodic Table arranges elements in order of increasing:', '["Atomic number", "Atomic mass", "Number of isotopes", "Melting point"]', 0, 'The Modern Periodic Law states that properties of elements are a periodic function of their atomic number, which is the basis of the Modern Periodic Table''s arrangement.', 'beginner'),
('education', 'class-10/science', 'periodic-classification', 'Mendeleev originally arranged elements in his periodic table in order of increasing:', '["Atomic mass", "Atomic number", "Valency only", "Density"]', 0, 'Mendeleev''s periodic table (1869) was based on increasing atomic mass, before the discovery of atomic number.', 'beginner'),
('education', 'class-10/science', 'periodic-classification', 'Elements placed in the same group of the periodic table generally have similar chemical properties because they have the same:', '["Number of valence electrons", "Atomic mass", "Number of shells", "Melting point"]', 0, 'Elements in the same group share the same number of valence electrons, which primarily determines chemical behavior.', 'beginner'),
('education', 'class-10/science', 'periodic-classification', 'In Dobereiner''s Law of Triads, elements were grouped in sets of:', '["3", "2", "4", "5"]', 0, 'Dobereiner grouped elements into triads of 3, where the atomic mass of the middle element was roughly the average of the other two.', 'beginner'),
('education', 'class-10/science', 'periodic-classification', 'Moving from left to right across a period in the Modern Periodic Table, atomic size generally:', '["Decreases", "Increases", "Remains constant", "Increases then decreases"]', 0, 'Across a period, increasing nuclear charge pulls electrons closer to the nucleus (with electrons added to the same shell), causing atomic size to generally decrease.', 'intermediate')
